new:
if (!bound) {
  await runtime.cancel(handle, "coordination_activation_binding_lost");
  await this.settlements.fail(
    activation.activation_id,
    "coordination_activation_binding_lost",
    false,
    this.retryBackoffMs,
  );
  return;
}

try {
  await runtime.assign(handle, worker.assignment);
} catch (error) {
  const reason = error instanceof Error ? error.message : String(error);
  try {
    await runtime.cancel(handle, "coordination_activation_start_failed");
  } catch {
    // Settlement below is authoritative; cancellation is best effort.
  }
  let spentUsd = 0;
  try {
    spentUsd = (await runtime.inspect(handle)).spentUsd ?? 0;
  } catch {
    // Preserve zero when runtime state cannot be read after start failure.
  }
  await this.settlements.finish(
    activation.activation_id,
    handle,
    false,
    reason,
    spentUsd,
    this.retryBackoffMs,
  );
}
